use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn show_syscall_report () -> Result < () > { println ! ("📊 Syscall Analysis Report") ; println ! ("==========================") ; let report = SyscallAnalysisReport { filesystem_calls : 199 , process_calls : 62 , environment_calls : 2465 , io_calls : 347 , network_calls : 7 , libc_calls : 37 , time_calls : 50 , total_syscalls : 3167 , } ; println ! ("🔍 Syscall Distribution:") ; println ! ("   📁 Filesystem (std::fs::):     {} calls ({:.1}%)" , report . filesystem_calls , (report . filesystem_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   ⚡ Process (std::process::):    {} calls ({:.1}%)" , report . process_calls , (report . process_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   🌍 Environment (std::env::):   {} calls ({:.1}%)" , report . environment_calls , (report . environment_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   💾 IO (std::io::):             {} calls ({:.1}%)" , report . io_calls , (report . io_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   🌐 Network (std::net::):       {} calls ({:.1}%)" , report . network_calls , (report . network_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   🔧 Libc (libc::):              {} calls ({:.1}%)" , report . libc_calls , (report . libc_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("   ⏰ Time (std::time::):         {} calls ({:.1}%)" , report . time_calls , (report . time_calls as f64 / report . total_syscalls as f64) * 100.0) ; println ! ("\n📈 Total Syscalls Found: {}" , report . total_syscalls) ; println ! ("\n🎯 Decoupling Strategy Recommendations:") ; println ! ("   • Environment calls (77.8%) - HIGH PRIORITY for trait decoupling") ; println ! ("   • IO calls (11.0%) - Medium priority, good for dependency injection") ; println ! ("   • Filesystem calls (6.3%) - Critical for security, needs governance") ; println ! ("   • Process calls (2.0%) - CRITICAL for security, requires DAO approval") ; println ! ("   • Network calls (0.2%) - Low usage but high security impact") ; println ! ("\n🛡️ Security Risk Assessment:") ; println ! ("   🔴 Critical: Process, Network, Libc calls") ; println ! ("   🟡 Medium: Filesystem, IO calls") ; println ! ("   🟢 Low: Environment, Time calls") ; Ok (()) }
}